"""Closed commerce notification owner APIs and compiled signed ADMIN template proxy."""
def extend(spec):
    from authorization import object_schema, parameter, operation, REF, UUID, VERSION
    schemas=spec['components']['schemas']
    schemas['NotificationContext']=object_schema({'orderNumber':{'type':'string'},'recipient':object_schema({'partyId':UUID,'email':{'type':'string','format':'email'}}),'total':{'type':'string','pattern':r'^\d+\.\d{2}$'},'currency':{'const':'NGN'},'trackingUrl':{'anyOf':[{'type':'string','format':'uri','pattern':'^https://'}, {'type':'null'}]}})
    receipt=object_schema({'jobId':UUID,'resourceId':UUID,'state':{'enum':['SENT','FAILED','SUPPRESSED','UNKNOWN']},'providerReference':{'type':'string','pattern':'^[A-Za-z0-9][A-Za-z0-9:_-]{0,159}$'}});receipt['required'].remove('providerReference');schemas['NotificationDelivery']=receipt
    schemas['NotificationAcknowledged']=object_schema({'acknowledged':{'type':'boolean'}})
    variables=object_schema({'type':{'const':'object'},'additionalProperties':{'const':False},'properties':{'type':'object','maxProperties':20,'propertyNames':{'enum':['code','expiresAt','orderNumber','total','currency','trackingUrl','refundStatus','amount','leadNumber','displayName','applicationNumber','opportunityTitle','confirmationUrl','quoteNumber','status','message']},'additionalProperties':object_schema({'type':{'const':'string'},'maxLength':{'type':'integer','minimum':1,'maximum':2000}})},'required':{'type':'array','uniqueItems':True,'items':{'type':'string'}}})
    template=object_schema({'code':{'type':'string','enum':['CONTACT_VERIFICATION','ORDER_PENDING','ORDER_PAID','ORDER_SHIPPED','ORDER_DELIVERED','ORDER_CANCELLED','REFUND_STATUS','LEAD_CREATED','DISTRIBUTOR_APPLICATION','DISTRIBUTOR_DECISION','QUOTE_OFFERED','NEWSLETTER_CONFIRMATION','CAREER_APPLICATION','STAFF_LEAD_REPLY','CART_RECOVERY']},'revision':{'type':'integer','minimum':1,'maximum':2147483647},'locale':{'type':'string','minLength':1,'maxLength':16},'channel':{'enum':['EMAIL','SMS','WHATSAPP']},'classification':{'enum':['TRANSACTIONAL','MARKETING']},'subject':{'type':'string','minLength':1,'maxLength':200},'body':{'type':'string','minLength':1,'maxLength':16384},'providerTemplateId':{'type':'string','pattern':'^[A-Za-z0-9][A-Za-z0-9:_-]{0,159}$'},'variablesSchema':variables,'active':{'type':'boolean'},'reason':{'type':'string','minLength':1,'maxLength':500}})
    for name in ('subject','providerTemplateId','reason'):template['required'].remove(name)
    schemas['NotificationTemplate']=template;schemas['NotificationTemplateView']=object_schema({'code':{'type':'string'},'revision':VERSION})
    spec['components']['securitySchemes']['integrationWorkload']['flows']['clientCredentials']['scopes'].update({'notification.read':'Minimal order notification context','notification.write':'Minimal job/state delivery accounting'})
    context=operation('API-122','Private exact nigson-integration workload notification.read, no signed user actor. Current active verified email recipient and minimal owned order context. No customer profile or dispatch. Integration validates the allowed job/order and rechecks current experience communication eligibility immediately before actual sending; context is never consent authorization. Unknown query/body rejected.','NotificationContext',[parameter('orderId','path',UUID,True)])
    delivery=operation('API-133','Private exact nigson-integration notification.write, no signed user actor. Immutable minimal job/state dedup and job/order binding, atomic audit and acknowledgement. Contradictory same-state receipt409; out-of-order states retained. SENT never changes order fulfillment. Failed work is exposed through the separately registered operations worker job proxy. No provider dispatch.','NotificationAcknowledged',[parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)])
    delivery['requestBody']={'required':True,'content':{'application/json':{'schema':REF('NotificationDelivery')}}}
    put=operation('API-165','Current ADMIN, no organization, recent MFA within15 minutes and cookie CSRF. Closed plain escaped placeholders with exact flat data schema; no expression evaluation. Compiled API-142 with templates.write_WITH_SIGNED_ADMIN assertion bound to exact body/method/path/correlation. Owned intent commits before unlocked KMS/token/HTTP. UNKNOWN retains the same private command UUID for acknowledgement reconciliation; never sends a message. Activated revisions immutable in the worker. Optional create If-Match is forwarded exactly when supplied, never guessed; actual upstream ETag is returned when supplied. Sender/template approvals and fresh dispatch consent remain separate activation/worker gates.','NotificationTemplateView',[parameter('If-Match','header',{'type':'string','pattern':'^"(0|[1-9][0-9]{0,18})"$'}),parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True),parameter('X-CSRF-TOKEN','header',{'type':'string','minLength':43,'maxLength':43},True)])
    put['requestBody']={'required':True,'content':{'application/json':{'schema':REF('NotificationTemplate')}}}
    for op,scope in ((context,'notification.read'),(delivery,'notification.write')):op['security']=[{'integrationWorkload':[scope]}]
    for op in (context,delivery,put):
        op['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}};op['responses']['422']['description']='Notification rule violation or feature disabled'
    put['responses']['200']['headers']['ETag']={'schema':{'type':'string'},'description':'Actual upstream quoted version if provided'}
    put['responses']['503']={'description':'Unavailable or uncertain acknowledgement; reconcile identical command identity','content':{'application/problem+json':{'schema':{'$ref':'../problem/problem.schema.json'}}}}
    spec['paths']['/internal/v1/notification-context/{orderId}']={'get':context};spec['paths']['/internal/v1/notification-deliveries']={'post':delivery};spec['paths']['/api/v1/staff/notification-templates']={'post':put}
    schemas['TwilioStatusAcknowledged']=object_schema({'received':{'type':'boolean'}})
    spec['components']['securitySchemes']['twilioSignature']={'type':'apiKey','in':'header','name':'X-Twilio-Signature','description':'Official Twilio signature over the complete form and the configured exact public URL plus jobId.'}
    callback={'operationId':'API-188','description':'Provider callback only. No browser credentials or Origin. Validate the complete bounded application/x-www-form-urlencoded parameter set using the official Twilio SDK and the fixed configured public URL plus canonical jobId; relay a minimized, scoped API-189 receipt and acknowledge only after Integration commits it. Duplicate and out-of-order statuses are durable and monotonic.','security':[{'twilioSignature':[]}],
      'parameters':[parameter('jobId','query',UUID,True),parameter('X-Twilio-Signature','header',{'type':'string','minLength':1,'maxLength':128},True)],
      'requestBody':{'required':True,'content':{'application/x-www-form-urlencoded':{'schema':{'type':'object','required':['AccountSid','MessageSid','MessageStatus'],'properties':{'AccountSid':{'type':'string','pattern':'^AC[a-fA-F0-9]{32}$'},'MessageSid':{'type':'string','pattern':'^SM[a-fA-F0-9]{32}$'},'MessageStatus':{'type':'string','enum':['accepted','scheduled','queued','sending','sent','delivered','read','failed','undelivered','canceled']},'ErrorCode':{'type':'string','pattern':'^[0-9]{3,6}$'}},'additionalProperties':{'type':'string','maxLength':4096},'maxProperties':100}}}},
      'responses':{'200':{'description':'Durable receipt acknowledged','content':{'application/json':{'schema':REF('TwilioStatusAcknowledged')}},'headers':{'Cache-Control':{'schema':{'const':'no-store'}}}},**{str(code):{'description':label,'content':{'application/problem+json':{'schema':{'$ref':'../problem/problem.schema.json'}}}} for code,label in [(400,'Invalid callback'),(401,'Authentication required'),(403,'Invalid signature or account'),(404,'Unknown notification job'),(415,'Unsupported content type'),(422,'Notification rule violation'),(503,'Receipt outcome unavailable or unknown')]}}
    }
    spec['paths']['/api/v1/webhooks/notifications/twilio/status']={'post':callback}
    return spec
